Object.assign(window.TEM8_DICTIONARY, {"justice":{"media":{"uk":"media/uk/justice__gb_1.mp3","us":"media/us/justice__us_1.mp3"},"oxford":{"phon":"ˈdʒʌstɪs","pos":"noun","senses":[{"en":"the fair treatment of people","cn":"公平；公正","g":"[uncountable]","ex":{"en":"She spent her life fighting for social justice and equality for women.","cn":"她一生都在为社会正义和妇女平等而奋斗。"}},{"en":"the quality of being fair or reasonable","cn":"公道；合理；公平合理","g":"[uncountable]","ex":{"en":"Who can deny the justice of their cause?","cn":"谁能否认他们的追求是合理的呢？"}},{"en":"the legal system used to punish people who have committed crimes","cn":"司法制度；法律制裁；审判","g":"[uncountable]","lab":"British English","ex":{"en":"the criminal justice system","cn":"刑事司法系统"}},{"en":"a judge in a court (also used before the name of a judge)","cn":"法官（亦作称谓）","g":"[countable]","lab":"North American English"},{"en":"used before the name of a judge in a court of appeal","cn":"（称谓）上诉法院法官","g":"[countable]","lab":"British English, Canadian English，，","ex":{"en":"Mr Justice Davies","cn":"上诉法院法官戴维斯先生"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"公平；公正；正义","en":"Justice is fairness in the way that people are treated.","ex":{"en":"He has a good overall sense of justice and fairness","cn":"他极富正义感和公平意识。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（理由、要求或论点的）合理，正当，正确，公道","en":"The justice of a cause, claim, or argument is its quality of being reasonable, fair, or right.","ex":{"en":"We are a minority and must win people round to the justice of our cause.","cn":"我们属于少数群体，必须赢得人们对我们的正义事业的支持。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"司法制度；法律制度","en":"Justice is the legal system that a country uses in order to deal with people who break the law.","ex":{"en":"Many in Toronto's black community feel that the justice system does not treat them fairly","cn":"多伦多的黑人群体中有很多人觉得司法制度对待他们有失公正。"}},{"pos":"N-COUNT 可数名词","cn":"法官","en":"A justice is a judge.","ex":{"en":"Thomas will be sworn in today as a justice on the Supreme Court.","cn":"托马斯今天将宣誓就任最高法院法官。"}},{"pos":"N-TITLE 头衔名词","cn":"（用于法官名前）…法官","en":"Justice is used before the names of judges.","ex":{"en":"A preliminary hearing was due to start today before Mr Justice Hutchison, but was adjourned.","cn":"今天法官哈奇森先生本来要主持一项预审，但暂时休庭了。"}},{"pos":"PHRASE 短语","cn":"将…绳之以法；把…缉拿归案","en":"If a criminal is brought to justice, he or she is punished for a crime by being arrested and tried in a court of law.","ex":{"en":"They demanded that those responsible be brought to justice","cn":"他们要求将责任人缉拿归案。"}},{"pos":"PHRASE 短语","cn":"准确地再现；逼真地重现","en":"To do justice to a person or thing means to reproduce them accurately and show how good they are.","ex":{"en":"The photograph I had seen didn't do her justice","cn":"我看到的那张照片把她拍得走样了。"}},{"pos":"PHRASE 短语","cn":"妥善应付；恰当处理；尽力全面做好","en":"If you do justice to someone or something, you deal with them properly and completely.","ex":{"en":"No one article can ever do justice to the topic of fraud","cn":"没有哪一篇文章能把欺诈这一话题讲得恰到好处。"}},{"pos":"PHRASE 短语","cn":"充分发挥能力；尽最大的努力","en":"If you do yourself justice, you do something as well as you are capable of doing it.","ex":{"en":"I don't think he could do himself justice playing for England","cn":"我认为他为英格兰队效力时不可能充分发挥自己的水平。"}},{"pos":"PHRASE 短语","cn":"不合法的待遇（或惩罚）","en":"If you describe someone's treatment or punishment as rough justice, you mean that it is not given according to the law.","ex":{"en":"Trial by television makes for very rough justice indeed.","cn":"电视庭审实际上会令审判不公。"}},{"pos":"PHRASE 短语","cn":"不公正的待遇（或惩罚）","en":"If you say that something is rough justice for someone, you mean that they have not been treated fairly.","ex":{"en":"It would have been rough justice had he been deprived of this important third European win.","cn":"要是他被剥夺了这一意义重大的第三个欧洲冠军头衔，那对他简直是太不公平了。"}}]},"examples":[{"en":"You cannot do justice to such a complex situation in just a few pages.","cn":"你不可能仅仅几页就将这么复杂的形势恰如其分地描述出来。"},{"en":"She didn't do herself justice in the exam.","cn":"她在考试中没有充分发挥出自己的水平。"}]},"juice":{"media":{"uk":"media/uk/juice__gb_1.mp3","us":"media/us/juice__us_1.mp3","img":["media/ldoce/img/orange_juice.jpg"]},"oxford":{"phon":"dʒuːs","pos":"noun","senses":[{"en":"the liquid that comes from fruit or vegetables; a drink made from this","cn":"果汁；菜汁；果汁（或菜汁）饮料","g":"[uncountable, countable]","ex":{"en":"a glass of fruit juice","cn":"一杯果汁"}},{"en":"the liquid that comes out of a piece of meat when it is cooked","cn":"肉汁","g":"[countable, usually plural, uncountable]","ex":{"en":"Use the juices of the meat to make gravy.","cn":"用肉汁来做卤汁。"}},{"en":"the liquid in the stomach that helps you to digest food","cn":"胃液；消化液","g":"[countable, usually plural]","ex":{"en":"digestive/gastric juices","cn":"消化液；胃液"}},{"en":"electricity","cn":"电","g":"[uncountable]","lab":"informal","ex":{"en":"My phone has run out of juice.","cn":"我的手机没电了。"}},{"en":"petrol","cn":"汽油","g":"[uncountable]","lab":"especially British English, informal，，"},{"en":"a liquid containing nicotine that is used in a device for vaping","cn":"烟油","g":"[uncountable]","lab":"informal"},{"en":"to get the juice out of fruit or vegetables","cn":"榨出（水果或蔬菜的）汁液；将…榨汁","ex":{"en":"Juice two oranges.","cn":"将两个橙子榨汁。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"果汁","en":"Juice is the liquid that can be obtained from a fruit.","ex":{"en":"...fresh orange juice","cn":"鲜榨橙汁"}},{"pos":"N-PLURAL 复数名词","cn":"肉汁","en":"The juices of a piece of meat are the liquid that comes out of it when you cook it.","ex":{"en":"When cooked, drain off the juices and put the meat in a processor or mincer.","cn":"肉煮熟后，沥干肉汁，将其放入食品加工机或绞肉机中。"}},{"pos":"N-PLURAL 复数名词","cn":"胃液;消化液","en":"The juices in your stomach are the fluids that help you to digest food."}]},"examples":[{"en":"Add the juice of two lemons.","cn":"加两个柠檬的汁。"},{"en":"Juice two oranges.","cn":"将两个橙子榨汁。"}]},"jury":{"oxford":{"phon":"ˈdʒʊəri","pos":"noun","senses":[{"en":"a group of members of the public who listen to the facts of a case in a court and decide whether or not somebody is guilty of a crime, or whether a claim has been proved","cn":"陪审团","lab":"especially in North American English","ex":{"en":"members of the jury","cn":"陪审团成员"}},{"en":"a group of people who decide who is the winner of a competition","cn":"（比赛的）评判委员会，裁判委员会，仲裁委员会","ex":{"en":"He was on the jury for this year's Booker Prize.","cn":"他是今年布克奖的评委。"}}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"陪审团","en":"In a court of law, the jury is the group of people who have been chosen from the general public to listen to the facts about a crime and to decide whether the person accused is guilty or not.","ex":{"en":"The jury convicted Mr Hampson of all offences.","cn":"陪审团裁定汉普森先生全部罪名成立。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"（竞赛的）评判委员会，裁判委员会","en":"A jury is a group of people who choose the winner of a competition.","ex":{"en":"I am not surprised that the Booker Prize jury included it on their shortlist.","cn":"我毫不惊讶布克奖评委会将其列在入选名单中。"}},{"pos":"PHRASE 短语","cn":"（某事）悬而未决，仍未达成定论","en":"If you say that the jury is out or that the jury is still out on a particular subject, you mean that people in general have still not made a decision or formed an opinion about that subject.","ex":{"en":"The jury is out on whether or not this is true","cn":"这是否属实仍未得出定论。"}}]},"media":{"uk":"media/uk/jury__gb_1.mp3","us":"media/us/jury__us_1.mp3"},"examples":[{"en":"The jury has/have returned a verdict of guilty.","cn":"陪审团已作出有罪裁定。"},{"en":"the right to trial by jury","cn":"经由陪审团审判的权利"}]},"judgment":{"lemma":"judgement","media":{"uk":"media/ldoce/hwd/bre/c/brelasdejudgment.mp3","us":"media/ldoce/hwd/ame/2/laadjudgment.mp3"}},"judge":{"media":{"uk":"media/uk/judge__gb_1.mp3","us":"media/us/judge__us_1.mp3"},"oxford":{"phon":"dʒʌdʒ","pos":"noun","senses":[{"en":"a person in a court who has the authority to decide how criminals should be punished or to make legal decisions","cn":"法官；审判员","sc":"in court","ex":{"en":"a High Court judge","cn":"高等法院的法官"}},{"en":"a person who decides who has won a competition","cn":"裁判员；评判员","sc":"in competition","ex":{"en":"The judges' decision is final.","cn":"裁判的决定为最终决定。"}},{"en":"a person who has the necessary knowledge or skills to give their opinion about the value or quality of somebody/something","cn":"鉴定人；鉴赏家","g":"[usually singular]","sc":"somebody who gives opinion","ex":{"en":"She's a good judge of character.","cn":"她很善于判断人的性格。"}},{"en":"to form an opinion about somebody/something, based on the information you have","cn":"判断；断定；认为","g":"[intransitive, transitive]","sc":"form opinion","ex":{"en":"As far as I can judge, all of them are to blame.","cn":"依我看，他们都应承担责任。"},"pos":"verb"},{"en":"to guess the size, amount, etc. of something","cn":"估计，猜测（大小、数量等）","g":"[transitive]","sc":"estimate","ex":{"en":"Young children are unable to judge the speed of traffic.","cn":"小孩子无法判断车辆的速度。"},"pos":"verb"},{"en":"to decide the result of a competition; to be the judge in a competition","cn":"裁判；评判；担任裁判","g":"[transitive, intransitive]","sc":"in competition","ex":{"en":"She was asked to judge the essay competition.","cn":"她被邀请担任作文比赛的评委。"},"pos":"verb"},{"en":"to give your opinion about somebody, especially when you think they are bad","cn":"评价；鉴定；（尤指）批评，指责","g":"[transitive, intransitive]","sc":"give opinion","ex":{"en":"What gives you the right to judge other people?","cn":"你有什么权利对别人评头论足？"},"pos":"verb"},{"en":"to decide whether somebody is guilty or innocent in a court","cn":"审判；审理；判决","g":"[transitive]","sc":"in court","ex":{"en":"to judge a case","cn":"审理案件"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"法官；审判官","en":"A judge is the person in a court of law who decides how the law should be applied, for example how criminals should be punished.","ex":{"en":"The judge adjourned the hearing until next Tuesday","cn":"法官将听证会延至下周二。"}},{"pos":"N-COUNT 可数名词","cn":"裁判员；评判员","en":"A judge is a person who decides who will be the winner of a competition.","ex":{"en":"A panel of judges is now selecting the finalists.","cn":"评判小组现在正选拔参加决赛的选手。"}},{"pos":"VERB 动词","cn":"为（竞赛等）担任裁判；评定","en":"If you judge something such as a competition, you decide who or what is the winner.","ex":{"en":"Colin Mitchell will judge the entries each week","cn":"科林·米切尔负责每周对参赛作品进行评判。"}},{"pos":"VERB 动词","cn":"判断；断定；评价；认为","en":"If you judge something or someone, you form an opinion about them after you have examined the evidence or thought carefully about them.","ex":{"en":"It will take a few more years to judge the impact of these ideas","cn":"要再花上几年的时间才能判断出这些想法的影响。"}},{"pos":"VERB 动词","cn":"估计，猜测（数量、大小、价值等）","en":"If you judge something, you guess its amount, size, or value or you guess what it is.","ex":{"en":"It is important to judge the weight of your washing load correctly","cn":"正确估计待洗衣物的重量很重要。"}},{"pos":"N-COUNT 可数名词","cn":"鉴赏家；鉴定人","en":"If someone is a good judge of something, they understand it and can make sensible decisions about it. If someone is a bad judge of something, they cannot do this.","ex":{"en":"I'm a pretty good judge of character","cn":"我很善于判断人的性格。"}},{"pos":"PREP-PHRASE 短语介词","cn":"根据…判断；根据…来看","en":"You use judging by ,judging from, or to judge from to introduce the reasons why you believe or think something.","ex":{"en":"Judging by the opinion polls, he seems to be succeeding","cn":"从民意测验来看，他似乎胜券在握。"}},{"pos":"PHRASE 短语","cn":"根据判断；看来","en":"If you say that something is true as far as you can judge or so far as you can judge, you are assuming that it is true, although you do not know all the facts about it.","ex":{"en":"They were typed records of his bets, going back a couple of years as far as I could judge","cn":"据我判断，这些是他过去几年下注打赌的书面记录。"}}]},"examples":[{"en":"‘I'm not sure that's a good way to do it.’ ‘ Let me be the judge of that. ’ “","cn":"我拿不准这样做好不好。” “就让我来判断吧。”"},{"en":"Each painting must be judged on its own merits.","cn":"任何一幅画都必须根据其本身的价值来评判。"}]},"judgements":{"lemma":"judgement"},"judgement":{"oxford":{"phon":"ˈdʒʌdʒmənt","pos":"noun","senses":[{"en":"the ability to make sensible decisions after carefully considering the best thing to do","cn":"判断力；识别力","g":"[uncountable]","ex":{"en":"good/poor/sound judgement","cn":"判断力强／弱；正确的判断力"}},{"en":"an opinion that you form about something after thinking about it carefully; the act of making this opinion known to others","cn":"看法；意见；评价","g":"[countable, uncountable]","ex":{"en":"In his portrait of the dictator he avoids any moral judgements.","cn":"在对独裁者的描述中，他避免做任何道德判断。"}},{"en":"the decision of a court or a judge","cn":"判决；裁决","g":"[countable, uncountable]","ex":{"en":"a judgment from the European Court of Justice","cn":"欧洲法院的判决"}},{"en":"something bad that happens to somebody that is thought to be a punishment from God","cn":"报应；天谴；（上帝对人的）审判","g":"[countable, usually singular]","lab":"formal"}]},"media":{"uk":"media/uk/judgement__gb_1.mp3","us":"media/us/judgement__us_1.mp3"},"examples":[{"en":"It's not something I can give you rules for; you'll have to use your judgement.","cn":"不是我把规则告诉你就行了，你得运用自己的判断力。"},{"en":"He achieved his aim more by luck than judgement.","cn":"他达到目的主要是靠运气而不是靠判断力。"}]},"june":{"media":{"uk":"media/uk/june__gb_1.mp3","us":"media/us/june__us_1.mp3"},"oxford":{"phon":"dʒuːn","pos":"noun","senses":[{"en":"the 6th month of the year, between May and July","cn":"六月","lab":"British English","ex":{"en":"She was born in June.","cn":"她出生在六月。"}},{"en":"a first name for girls","cn":"朱妮（女子名）"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"六月","en":"June is the sixth month of the year in the Western calendar.","ex":{"en":"He spent two and a half weeks with us in June 1986","cn":"1986年6月他和我们一起呆了两周半。"}}]}},"juices":{"lemma":"juice","media":{"uk":"media/uk/juice__gb_1.mp3","us":"media/us/juice__us_1.mp3"}},"judgments":{"oxford":{"phon":"ˈdʒʌdʒmənt","pos":"noun","senses":[{"en":"the ability to make sensible decisions after carefully considering the best thing to do","cn":"判断力；识别力"},{"en":"an opinion that you form about sth after thinking about it carefully; the act of making this opinion known to others","cn":"看法；意见；评价"}]}},"juniper":{"oxford":{"phon":"ˈdʒuːnɪpə(r)","pos":"noun","senses":[{"en":"a bush or small tree with purple berries that are used in medicine and to add taste to gin","cn":"刺柏，桧柏（有些种的浆果可作药用和给杜松子酒调味）"},{"en":"a first name for girls","cn":"朱尼珀（女子名）","pos":""}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"刺柏，桧（其紫色浆果可用于烹饪和制药）","en":"A juniper is an evergreen bush with purple berries which can be used in cooking and medicine."}]},"media":{"uk":"media/uk/juniper__gb_1.mp3","us":"media/us/juniper__us_1.mp3"}},"justify":{"media":{"uk":"media/uk/justify__gb_1.mp3","us":"media/us/justify__us_1.mp3"},"oxford":{"phon":"ˈdʒʌstɪfaɪ","pos":"verb","senses":[{"en":"to show that somebody/something is right or reasonable","cn":"证明…正确（或正当、有理）","ex":{"en":"How can they justify paying such huge salaries?","cn":"他们怎能证明付这么大笔薪金是正当的呢？"}},{"en":"to give an explanation or excuse for something or for doing something","cn":"对…作出解释；为…辩解（或辩护）","ex":{"en":"The senator made an attempt to justify his actions.","cn":"参议员试图证明他的行为是合理的。"}},{"en":"to arrange lines of printed text so that one or both edges are straight","cn":"将（打印的字行）调整为边缘对齐","lab":"specialist"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"证明（决定、行为或想法）正当；表明…必要","en":"To justify a decision, action, or idea means to show or prove that it is reasonable or necessary.","ex":{"en":"No argument can justify a war","cn":"任何理由都不能为战争开脱。"}},{"pos":"VERB 动词","cn":"调整（打印文本）；使齐行；使每行排齐","en":"To justify printed text means to adjust the spaces between the words so that each line of type is exactly the same length.","ex":{"en":"Click on this icon to align or justify text.","cn":"点击这个图标使文本排齐。"}}]},"examples":[{"en":"How can they justify paying such huge salaries?","cn":"他们怎能证明付这么大笔薪金是正当的呢？"},{"en":"Her success had justified the faith her teachers had put in her.","cn":"她的成功证明了老师对她的信任是正确的。"}]},"justification":{"oxford":{"phon":"ˌdʒʌstɪfɪˈkeɪʃn","pos":"noun","senses":[{"en":"a good reason why something exists or is done","cn":"正当理由","ex":{"en":"I can see no possible justification for any further tax increases.","cn":"我看不出还能提出什么理由再加税。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"正当理由；合理的解释","en":"A justification for something is an acceptable reason or explanation for it.","ex":{"en":"To me the only justification for a zoo is educational","cn":"对我来说，动物园存在的唯一正当理由是其教育作用。"}}]},"media":{"uk":"media/uk/justification__gb_1.mp3","us":"media/us/justification__us_1.mp3"},"examples":[{"en":"All I can say in justification of her actions is that she was under a lot of pressure at work.","cn":"我唯一能为她的行为辩解的理由是她工作压力很大。"},{"en":"I can see no possible justification for any further tax increases.","cn":"我看不出还能提出什么理由来加税了。"}]},"jump":{"media":{"img":["media/pic/equestriansports_comp.jpg","media/thumb/showjumping.jpg"],"uk":"media/uk/jump__gb_1.mp3","us":"media/us/jump__us_1.mp3"},"oxford":{"phon":"dʒʌmp","pos":"verb","senses":[{"en":"to move quickly off the ground or away from a surface by pushing yourself with your legs and feet","cn":"跳；跃；跳跃","g":"[intransitive]","sc":"move off/to ground","ex":{"en":"‘Quick, jump!’ he shouted.","cn":"“赶快，跳！”他大声叫道。"}},{"en":"to pass over something by jumping","cn":"跳过；跃过；跨越","g":"[intransitive, transitive]","sc":"pass over something","ex":{"en":"He jumped over the wall to get away.","cn":"他跳墙逃跑。"}},{"en":"to move quickly and suddenly","cn":"突然快速移动","g":"[intransitive]","sc":"move quickly","ex":{"en":"He jumped to his feet when they called his name.","cn":"他们叫到他的名字时他一下子就站了起来。"}},{"en":"to make a sudden movement because of surprise, fear or excitement","cn":"（因吃惊、害怕或激动而）猛地一动，突然一跳","g":"[intransitive]","sc":"move quickly","ex":{"en":"A loud bang made me jump.","cn":"砰的一声巨响吓我一跳。"}},{"en":"to rise suddenly by a large amount","cn":"突升；猛涨；激增","g":"[intransitive]","sc":"increase","ex":{"en":"Prices jumped by 60% last year.","cn":"去年，物价暴涨 60%。"}},{"en":"to change suddenly from one subject to another","cn":"突然改变，突然转换（话题、题目）","g":"[intransitive]","sc":"change suddenly","ex":{"en":"I couldn't follow the talk because he kept jumping about from one topic to another.","cn":"我听不明白他的讲话，因为他老是转换话题。"}},{"en":"to leave out something and pass to a further point or stage","cn":"略去；略过；跳过","g":"[transitive]","sc":"leave out","ex":{"en":"You seem to have jumped several steps in the argument.","cn":"你在论证中似乎略去了好几个步骤。"}},{"en":"to move suddenly and unexpectedly, especially out of the correct position","cn":"突然跳出正常位置；意外地离开正常位置","g":"[intransitive]","sc":"of machine/device","ex":{"en":"The needle jumped across the dial.","cn":"指针突然从刻度盘的一端跳到另一端。"}},{"en":"to attack somebody suddenly","cn":"突然袭击（某人）；猛地扑向（某人）","g":"[transitive, intransitive]","lab":"informal","sc":"attack","ex":{"en":"The thieves jumped him in a dark alleyway.","cn":"一伙盗贼在一条漆黑的小巷里突然扑向他。"}},{"en":"to get on a vehicle very quickly, especially in a way that is dangerous or illegal","cn":"跳上（车）（尤指行为危险或违法）","g":"[transitive]","lab":"North American English","sc":"vehicle","ex":{"en":"to jump a bus","cn":"跳上公共汽车"}},{"en":"to start the engine of a car by connecting the battery to the battery of another car with jump leads","cn":"用跨接引线启动（汽车发动机）","lab":"North American English","sc":"vehicle"},{"en":"to put a lot of energy into starting a process or an activity or into making it start more quickly","cn":"全力启动；加快开展","lab":"North American English","sc":"vehicle"},{"en":"to be very lively","cn":"欢跃；雀跃","g":"[intransitive]","lab":"informal","sc":"be lively","ex":{"en":"The bar's jumping tonight.","cn":"今晚酒吧里气氛活跃。"}},{"en":"an act of jumping","cn":"跳；跃；跳跃","sc":"movement","ex":{"en":"to do a parachute jump","cn":"跳伞"},"pos":"noun"},{"en":"a barrier like a narrow fence that a horse or a runner has to jump over in a race or competition","cn":"（比赛中需跳过的）障碍物","sc":"barrier","ex":{"en":"The horse fell at the last jump.","cn":"那匹马在跨越最后一个障碍物时跌倒了。"},"pos":"noun"},{"en":"a sudden increase in amount, price or value","cn":"突升；猛涨；激增","sc":"increase","ex":{"en":"unusually large price jumps","cn":"非同寻常的大幅度涨价"},"pos":"noun"},{"en":"a large or sudden change","cn":"巨变；突变","sc":"change","ex":{"en":"Is he good enough to make the jump into Formula One?","cn":"他是否足够优秀，可以跳级进入一级方程式？"},"pos":"noun"},{"en":"a sudden movement caused by shock or surprise","cn":"（受惊吓引起的）猛的一动，突然一跳","sc":"sudden movement","ex":{"en":"I sat up with a jump.","cn":"我惊得一下子坐了起来。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"跳；跃；跳跃","en":"If you jump, you bend your knees, push against the ground with your feet, and move quickly upwards into the air.","ex":{"en":"I jumped over the fence","cn":"我跳过了栅栏。"}},{"pos":"VERB 动词","cn":"跳下；跃出","en":"If you jump from something above the ground, you deliberately push yourself into the air so that you drop towards the ground.","ex":{"en":"He jumped out of a third-floor window","cn":"他从3楼的窗户跳了出去。"}},{"pos":"VERB 动词","cn":"跳过，跃过，跨越（栅栏等）","en":"If you jump something such as a fence, you move quickly up and through the air over or across it.","ex":{"en":"He jumped the first fence beautifully.","cn":"他轻松地跨过第一道栏。"}},{"pos":"VERB 动词","cn":"快速移动；一跃而起","en":"If you jump somewhere, you move there quickly and suddenly.","ex":{"en":"Adam jumped from his seat at the girl's cry","cn":"女孩儿一哭，亚当立即从座位上跳了起来。"}},{"pos":"VERB 动词","cn":"（因害怕或吃惊）猛地一跳，突然一跳","en":"If something makes you jump, it makes you make a sudden movement because you are frightened or surprised.","ex":{"en":"The phone shrilled, making her jump.","cn":"刺耳的电话铃响了起来，把她吓了一跳。"}},{"pos":"VERB 动词","cn":"（数量或水平）突升，激增","en":"If an amount or level jumps, it suddenly increases or rises by a large amount in a short time.","ex":{"en":"Sales jumped from $94 million to over $101 million","cn":"销售额从9, 400万美元激增到了1.0 1亿美元。"}},{"pos":"VERB 动词","cn":"插（队）；不按顺序排（队）","en":"If someone jumps a queue, they move to the front of it and are served or dealt with before it is their turn.","ex":{"en":"The prince refused to jump the queue for treatment at the local hospital.","cn":"王子在本地医院候诊时拒绝插队。"}},{"pos":"VERB 动词","cn":"突然袭击；出其不意地攻击","en":"If someone jumps on you or jumps you, they attack you suddenly or unexpectedly.","ex":{"en":"A week later, the same guys jumped on me on our own front lawn","cn":"一个星期后，同一伙人又在我们家门口的草坪上袭击了我。"}},{"pos":"VERB 动词","cn":"迫不及待地接受，欣然应承（建议或机会）","en":"If you jump at an offer or opportunity, you accept it quickly and eagerly.","ex":{"en":"Members of the public would jump at the chance to become part owners of the corporation.","cn":"一些公众会迫不及待地想要抓住机会成为这家公司的持股人。"}},{"pos":"VERB 动词","cn":"毫不犹豫地批评；立即责备","en":"If someone jumps on you, they quickly criticize you if you do something that they do not approve of.","ex":{"en":"A lot of people jumped on me about that, you know.","cn":"你知道，那件事让很多人逮着机会批评我。"}},{"pos":"PHRASE 短语","cn":"比…占先；胜过；优于","en":"If you get a jump on something or someone or get the jump on them, you gain an advantage over them.","ex":{"en":"Helicopters helped fire crews get a jump on the blaze","cn":"直升机帮助消防队员控制住了火势。"}},{"pos":"PHRASE 短语","cn":"非常激动；欣喜若狂；暴跳如雷","en":"If you say that someone is jumping up and down, you mean they are very excited, happy, or angry about something.","ex":{"en":"I don't think a lot of people will jump up and down and say 'thank heavens'..","cn":"我并不认为很多人会欣喜若狂地说“感谢上帝”。"}},{"pos":"","cn":"","en":"to jump on the bandwagon→see: ; to jump bail→see: ; to jump to a conclusion→see: ; to jump the gun→see: ; to jump for joy→see: ; to jump out of one's skin→see: ;"},{"pos":"","cn":"","en":"相关词组：jump in jump out"}]},"examples":[{"en":"The story then jumps from her childhood in New York to her first visit to London.","cn":"故事接着从她在纽约的童年一下子转到她第一次去伦敦。"},{"en":"Before she could reply Peter jumped in with an objection.","cn":"她还没来得及回答，彼得就迫不及待地表示反对。"}]},"justified":{"media":{"uk":"media/uk/justified__gb_1.mp3","us":"media/us/justified__us_1.mp3"},"oxford":{"phon":"ˈdʒʌstɪfaɪd","pos":"adjective","senses":[{"en":"having a good reason for doing something","cn":"（做某事）有正当理由的","ex":{"en":"She felt fully justified in asking for her money back.","cn":"她认为有充分的理由要求退款。"}},{"en":"existing or done for a good reason","cn":"事出有因的；合乎情理的","ex":{"en":"His fears proved justified.","cn":"他的恐惧后来证明是有原因的。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（决定、行为或想法）正当的，合理的","en":"If you describe a decision, action, or idea as justified, you think it is reasonable and acceptable.","ex":{"en":"In my opinion, the decision was wholly justified.","cn":"我认为，这个决定完全合理。"}},{"pos":"ADJ 形容词","cn":"（做…）有正当理由的","en":"If you think that someone is justified in doing something, you think that their reasons for doing it are good and valid.","ex":{"en":"He's absolutely justified in resigning. He was treated shamefully.","cn":"他完全有理由辞职。他受到了侮辱。"}}]},"examples":[{"en":"She felt fully justified in asking for her money back.","cn":"她认为有充分的理由要求退款。"},{"en":"His fears proved justified.","cn":"他的恐惧后来证明是有原因的。"}],"base":"justify"},"judaism":{"oxford":{"phon":"ˈdʒuːdeɪɪzəm","pos":"noun","senses":[{"en":"the religion of the Jewish people, based mainly on the first five books of the Bible and the Talmud","cn":"犹太教"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"犹太教","en":"Judaism is the religion of the Jewish people. It is based on the Old Testament of the Bible and the Talmud."}]},"media":{"uk":"media/uk/judaism__gb_1.mp3","us":"media/us/judaism__us_1.mp3"},"examples":[{"en":"Judaic tradition","cn":"犹太教传统"}]},"judicial":{"oxford":{"phon":"dʒuˈdɪʃl","pos":"adjective","senses":[{"en":"connected with a court, a judge or legal judgement","cn":"法庭的；法官的；审判的；司法的","ex":{"en":"judicial powers","cn":"司法权"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"司法的；法庭的；审判的","en":"Judicial means relating to the legal system and to judgments made in a court of law.","ex":{"en":"...an independent judicial inquiry","cn":"独立的司法调查"}}]},"media":{"uk":"media/uk/judicial__gb_1.mp3","us":"media/us/judicial__us_1.mp3"},"examples":[{"en":"the judicial process/system","cn":"司法程序/系统"},{"en":"judicial powers","cn":"司法权"}]},"july":{"media":{"uk":"media/uk/july__gb_1.mp3","us":"media/us/july__us_1.mp3"},"oxford":{"phon":"dʒuˈlaɪ","pos":"noun","senses":[{"en":"the 7th month of the year, between June and August","cn":"七月","lab":"British English","ex":{"en":"She was born in July.","cn":"她出生在七月。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"七月","en":"July is the seventh month of the year in the Western calendar.","ex":{"en":"In late July 1914, he and Violet spent a few days with friends near Berwick-upon-Tweed","cn":"1914年7月下旬，他和维奥莱特与几个朋友在特威德河畔贝里克附近度过了几天。"}}]}},"jubilant":{"media":{"uk":"media/uk/jubilant__gb_1.mp3","us":"media/us/jubilant__us_1.mp3"},"oxford":{"phon":"ˈdʒuːbɪlənt","pos":"adjective","senses":[{"en":"feeling or showing great happiness because of a success","cn":"喜气洋洋的；欢欣鼓舞的；欢呼雀跃的","ex":{"en":"The fans were in jubilant mood after the victory.","cn":"胜利后，球迷们心情愉悦。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（因为成功而）欢欣鼓舞的，欣喜若狂的","en":"If you are jubilant, you feel extremely happy because of a success.","ex":{"en":"Ferdinand was jubilant after making an impressive comeback from a month on the injured list.","cn":"费迪南德受伤休养了一个月，重新归队后表现非常出色，他简直高兴极了。"}}]},"examples":[{"en":"Radicals were jubilant at getting rid of him.","cn":"激进分子因为除掉了他而欣喜若狂。"},{"en":"The fans were in jubilant mood as they left the stadium.","cn":"球迷们离开体育场时兴高采烈。"}]},"junction":{"media":{"uk":"media/uk/junction__gb_1.mp3","us":"media/us/junction__us_1.mp3"},"oxford":{"phon":"ˈdʒʌŋkʃn","pos":"noun","senses":[{"en":"the place where two or more roads or railway lines meet","cn":"（公路或铁路的）交叉路口，汇合处，枢纽站","lab":"especially British English","ex":{"en":"It was near the junction of City Road and Old Street.","cn":"那是在城市路与老街的交叉路口附近。"}},{"en":"a place where two or more cables, rivers or other things meet or are joined","cn":"（电缆的）主接点；（河流的）汇合处；接合点","ex":{"en":"a telephone junction box","cn":"电话分线盒"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"（公路的）交叉路口；（公路或铁路的）汇合处，枢纽站","en":"A junction is a place where roads or railway lines join.","ex":{"en":"Follow the road to a junction and turn left","cn":"沿着这条路到交叉路口，然后左转。"}}]},"examples":[{"en":"It was near the junction of City Road and Old Street.","cn":"那是在城市路与老街的交叉路口附近。"},{"en":"Come off the motorway at junction 6.","cn":"在 6 号交叉路口驶离高速公路。"}]},"just":{"media":{"uk":"media/uk/just__gb_1.mp3","us":"media/us/just__us_1.mp3"},"oxford":{"phon":"dʒʌst","pos":"adverb","senses":[{"en":"only","cn":"仅仅；只不过","ex":{"en":"There is just one method that might work.","cn":"只有一个方法可能起作用。"}},{"en":"simply","cn":"只是；仅仅是","lab":"informal","ex":{"en":"It was just an ordinary day.","cn":"那只是普普通通的一天。"}},{"en":"by a small amount","cn":"刚好；差一点就不；勉强","ex":{"en":"You've just missed her.","cn":"你刚好错过了她。"}},{"en":"used to say that you/somebody did something or something happened very recently","cn":"刚才；方才","lab":"especially North American English","ex":{"en":"I've just heard the news.","cn":"我刚听到这个消息。"}},{"en":"at this/that moment; now","cn":"此时；那时；眼下；现在","ex":{"en":"I'm just finishing my book.","cn":"眼下我正在完成我的一本书。"}},{"en":"exactly","cn":"正好；恰好","lab":"British English","ex":{"en":"This jacket is just my size.","cn":"这件夹克正合我的尺码。"}},{"en":"at the same moment as","cn":"正当…时","ex":{"en":"The clock struck six just as I arrived.","cn":"我到达时，时钟正敲六点。"}},{"en":"no less than; equally","cn":"不亚于；同样","ex":{"en":"She's just as smart as her sister.","cn":"她与她姐姐一样聪明。"}},{"en":"going to do something only a few moments from now or then","cn":"正要；正准备；马上就要","ex":{"en":"The water's just about to boil.","cn":"水马上就要开了。"}},{"en":"really; completely","cn":"真正地；确实；完全","lab":"informal","ex":{"en":"The food was just wonderful!","cn":"那吃的实在是好极了！"}},{"en":"used in orders to get somebody’s attention, give permission, etc.","cn":"（引起注意、表示允许等）请，就","ex":{"en":"Just listen to what I'm saying, will you!","cn":"你就听我说好吗？"}},{"en":"used to make a polite request, excuse, etc.","cn":"（提出请求、表示歉意等）请","ex":{"en":"Could you just help me with this box, please?","cn":"请帮我搬一搬这箱子好吗？"}},{"en":"used to show a slight possibility that something is true or will happen","cn":"（表示稍有可能）可能，也许","ex":{"en":"Try asking Mike—he might just know the answer.","cn":"问问迈克吧，没准儿他知道答案。"}},{"en":"used to agree with somebody","cn":"（表示赞同）","ex":{"en":"‘He's very pompous.’ ‘Isn't he just?’","cn":"“他很自负。”“可不是吗？”"}},{"en":"that most people consider to be morally fair and reasonable","cn":"公正的；正义的；正当的；合理的","ex":{"en":"a just decision/law/society","cn":"公正的判决／法律／社会"},"pos":"adjective"},{"en":"people who are just","cn":"正直的人；公正的人","g":"[plural]","pos":"adjective"},{"en":"appropriate in a particular situation","cn":"合适的；恰当的","ex":{"en":"a just reward/punishment","cn":"应有的报偿／惩罚"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"刚才；方才；刚刚","en":"You use just to say that something happened a very short time ago, or is starting to happen at the present time. For example, if you say that someone has just arrived, you mean that they arrived a very short time ago.","ex":{"en":"I've just bought a new house","cn":"我刚买了栋新房子。"}},{"pos":"ADV 副词","cn":"正在；正要；正准备","en":"If you say that you are just doing something, you mean that you are doing it now and will finish it very soon. If you say that you are just about to do something, or just going to do it, you mean that you will do it very soon.","ex":{"en":"I'm just making the sauce for the cauliflower","cn":"我正在弄花椰菜的调味汁呢。"}},{"pos":"ADV 副词","cn":"（用于强调）正，就，恰恰（在某个时刻）","en":"You can use just to emphasize that something is happening at exactly the moment of speaking or at exactly the moment that you are talking about.","ex":{"en":"Randall would just now be getting the Sunday paper","cn":"兰德尔这个时候应该正在拿周日的报纸。"}},{"pos":"ADV 副词","cn":"（尤用于纠正错误的观点）只是，仅仅是","en":"You use just to indicate that something is no more important, interesting, or difficult, for example, than you say it is, especially when you want to correct a wrong idea that someone may get or has already got.","ex":{"en":"It's just a suggestion","cn":"这只是个建议。"}},{"pos":"ADV 副词","cn":"（用于强调所谈的只是一小部分而非全部）仅仅是，只不过是","en":"You use just to emphasize that you are talking about a small part, not the whole of an amount.","ex":{"en":"That's just one example of the kind of experiments you can do","cn":"这只不过是你可以做的各种试验中的一例罢了。"}},{"pos":"ADV 副词","cn":"（用于强调数量少或时间短）只是，仅仅","en":"You use just to emphasize how small an amount is or how short a length of time is.","ex":{"en":"Stephanie and David redecorated a room in just three days","cn":"斯蒂法妮和戴维仅仅花了3天就把一个房间装饰一新。"}},{"pos":"ADV 副词","cn":"（用于动词前表示事情的结果糟糕，很可能导致局面恶化）只（会），只不过","en":"You can use just in front of a verb to indicate that the result of something is unfortunate or undesirable and is likely to make the situation worse rather than better.","ex":{"en":"Leaving like I did just made it worse","cn":"像我那样一走了之只会让事情变得更糟。"}},{"pos":"ADV 副词","cn":"（用于表示情况在很小的程度上属实）刚刚，勉强，差一点就不","en":"You use just to indicate that what you are saying is the case, but only by a very small degree or amount.","ex":{"en":"Her hand was just visible by the light from the sitting room","cn":"借着起居室的灯光，勉强能看见她的手。"}},{"pos":"ADV 副词","cn":"（与might，may和could连用，表示稍有可能）可能，也许","en":"You use just with 'might,' 'may,' and 'could', when you mean that there is a small chance of something happening, even though it is not very likely.","ex":{"en":"It's an old trick but it just might work","cn":"这是个老掉牙的把戏了，不过也许会有用。"}},{"pos":"ADV 副词","cn":"（用于加强语气，表示生气、赞美、肯定等）硬是，就是，简直","en":"You use just to emphasize the following word or phrase, in order to express feelings such as annoyance, admiration, or certainty.","ex":{"en":"She just won't relax","cn":"她就是放松不下来。"}},{"pos":"ADV 副词","cn":"（用于指示、礼貌的请求或表示意图的陈述，用来弱化语气）请，只要，只管…就好了","en":"You use just with instructions, polite requests, or statements of intention, to make your request or statement seem less difficult.","ex":{"en":"Could you just give us a description of your cat?","cn":"能否请您向我们描述一下您的猫？"}},{"pos":"ADV 副词","cn":"请稍候；稍等一下","en":"You use just in expressions such as just a minute and just a moment to ask someone to wait for a short time.","ex":{"en":"'Let me in, Di.' — 'Okay. Just a minute.'","cn":"“让我进来，迪。”——“好的。稍等一下。”"}},{"pos":"ADV 副词","cn":"（用于打断某人，以表示不同意、解释某事或让其保持冷静）稍等一下，且慢","en":"You can use just in expressions such as just a minute and just a moment to interrupt someone, for example in order to disagree with them, explain something, or calm them down.","ex":{"en":"Well, now just a second, I don't altogether agree with the premise.","cn":"嗯，且慢，我并不完全同意这个前提。"}},{"pos":"ADV 副词","cn":"（用于否定附加问句，表示完全赞同）难道不是吗，确实如此","en":"You can use just with negative question tags, for example 'isn't he just?' and 'don't they just!', to say that you agree completely with what has been said.","ex":{"en":"'That's crazy,' I said. 'Isn't it just?' he said","cn":"“那简直是疯了，”我说。“谁说不是呢？”他说。"}},{"pos":"ADV 副词","cn":"（表示完全可以想象）完全，简直","en":"If you say that you can just see or hear something, you mean that it is easy for you to imagine seeing or hearing it.","ex":{"en":"I can just see the nasty suspicious looks I'd be getting from you if we started whispering together","cn":"要是我们开始凑在一起交头接耳，我简直能想象到你那种令人讨厌的怀疑的目光了。"}},{"pos":"ADV 副词","cn":"确切地；精确地","en":"You use just to mean exactly, when you are specifying something precisely or asking for precise information.","ex":{"en":"It is really not clear just why he became a Socialist","cn":"他为何成为社会党人的确切原因实际上还不清楚。"}},{"pos":"ADV 副词","cn":"恰恰是；正是","en":"You use just to emphasize that a particular thing is exactly what is needed or fits a particular description exactly.","ex":{"en":"Kiwi fruit are just the thing for a healthy snack","cn":"猕猴桃作为有益健康的零食是再好不过了。"}},{"pos":"ADV 副词","cn":"正（如）；正（像）","en":"You use just in expressions such as just like ,just as...as, and just the same when you are emphasizing the similarity between two things or two people.","ex":{"en":"Behind the facade they are just like the rest of us","cn":"在那副外表背后，他们和我们大家是完全一样的。"}},{"pos":"PHRASE 短语","cn":"差不多；几乎；近乎","en":"You use just about to indicate that what you are talking about is so close to being the case that it can be regarded as being the case.","ex":{"en":"There are those who believe that Nick Price is just about the best golfer in the world","cn":"有一些人认为尼克·普赖斯几乎就是世界上最优秀的高尔夫球运动员了。"}},{"pos":"PHRASE 短语","cn":"勉强；差一点就不","en":"You use just about to indicate that what you are talking about is in fact the case, but only by a very small degree or amount.","ex":{"en":"I can just about tolerate it at the moment","cn":"当时我差一点就忍受不了了。"}},{"pos":"PHRASE 短语","cn":"（用于表示接近于某一具体数量）几乎，差不多","en":"Just on is used in mentioning an almost exact number or amount.","ex":{"en":"Eve, squinting at the clock, saw it was just on 7 a.m","cn":"伊夫眯着眼瞥了一下钟，看到差不多是早上7点钟。"}},{"pos":"CONVENTION 惯用语","cn":"对极了；正是","en":"Just so is used to agree with or confirm a statement that has been made.","ex":{"en":"'She has a large flat in Mayfair.' — 'Just so.'","cn":"“她在梅费尔有个大公寓。”——“正是。”"}},{"pos":"PHRASE 短语","cn":"严格按照要求的","en":"If things are just so, they are done or arranged exactly as they should be or exactly as someone wants them.","ex":{"en":"I do her hair, and it has to be just so.","cn":"我必须得按她的要求为她做头发。"}},{"pos":"PHRASE 短语","cn":"（用于弱化抱怨、给出建议或理由时的语气）只不过，只是","en":"You use the expression it's just that when you are making a complaint, suggestion, or excuse, so that the person you are talking to will not get annoyed with you.","ex":{"en":"I'm sorry I struck you. I didn't mean to. It's just that I was so mad","cn":"很抱歉我打了你。我不是有意的，只不过我当时气极了。"}},{"pos":"","cn":"","en":"just my luck→see: ; not just→see: ; just now→see: ; only just→see: ; it just goes to show→see: ;"},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"公正的；正当的；正义的；合理的","en":"If you describe a situation, action, or idea as just, you mean that it is right or acceptable according to particular moral principles, such as respect for all human beings.","ex":{"en":"In a just society there must be a system whereby people can seek redress through the courts","cn":"在一个公正的社会中，一定会有一套人们可以通过法庭寻求赔偿的体制。"}},{"pos":"","cn":"","en":"to get your just deserts→see: ;"}]},"examples":[{"en":"‘Is Mr Burns available?’ ‘Just a second, please, I'll check.’ “","cn":"我可以见伯恩斯先生吗？” “请稍等一会儿，我来查一下。”"},{"en":"‘Can I help you?’ ‘No thanks, I'm just looking. ’ (= in a shop/store) “","cn":"我能为你做点什么吗？” “不用，谢谢，我只是看看。”"}]},"justifiable":{"media":{"uk":"media/uk/justifiable__gb_1.mp3","us":"media/us/justifiable__us_1.mp3"},"oxford":{"phon":"ˌdʒʌstɪˈfaɪəbl","pos":"adjective","senses":[{"en":"existing or done for a good reason, and therefore acceptable","cn":"有理由的；可证明是正当的；情有可原的","ex":{"en":"She took a justifiable pride in her son's achievements.","cn":"她理所当然地为儿子的成就感到自豪。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有理由的；无可非议的；情有可原的","en":"An action, situation, emotion, or idea that is justifiable is acceptable or correct because there is a good reason for it.","ex":{"en":"The violence of the revolutionary years was justifiable on the grounds of political necessity.","cn":"出于政治需要，革命年代的暴力行为是情有可原的。"}}]},"examples":[{"en":"The university can be justifiably proud of its record.","cn":"这所大学值得为自己的纪录而自豪。"},{"en":"justifiable pride","cn":"无可非议的自豪感"}]},"juggling":{"oxford":{"phon":"ˈdʒʌɡl","pos":"verb","senses":[{"en":"to throw a set of three or more objects such as balls into the air and catch and throw them again quickly, one at a time","cn":"玩杂耍（连续向空中抛接多个物体）"},{"en":"to try to deal with two or more important jobs or activities at the same time so that you can fit all of them into your life","cn":"尽力同时应付（两个或更多的重要工作或活动）"}]},"media":{"uk":"media/ldoce/hwd/bre/d/juggling1004.mp3","us":"media/ldoce/hwd/ame/c/juggling1004a.mp3","img":["media/ldoce/img/juggling.jpg"]},"examples":[{"en":"It took a lot of juggling and rearrangement of figures before the loan was approved.","cn":"这笔贷款获批之前﹐数额经过了多次调整和修改。"},{"en":"a display of juggling","cn":"杂耍表演"}]},"jungles":{"lemma":"jungle"},"jumping":{"lemma":"jump"},"judging":{"lemma":"judge"},"jutting":{"lemma":"jut","media":{"uk":"media/ldoce/hwd/bre/e/jut0205.mp3","us":"media/ldoce/hwd/ame/7/jut.mp3"}},"jumped":{"lemma":"jump"},"jug":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（带柄的）罐，壶","en":"A jug is a cylindrical container with a handle and is used for holding and pouring liquids.","ex":{"en":"...a jug of water.","cn":"一壶水"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a container with a wide curved opening at the top and a handle, used especially at meals for pouring liquids 〔","cn":"有柄带嘴的〕壶﹐罐"},{"en":"a deep round container with a very narrow opening at the top and a handle, used for holding liquids 〔","cn":"细口带柄的〕大壶﹐大罐"},{"en":"the amount of liquid that a jug will hold","cn":"一壶之量﹐一罐之量"}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"Many people buy their milk in a jug , a large container with a handle and a small opening at the top."}]},"collocations":{"phrases":["ADJ. measuring | china, earthenware, enamel, enamelled, glass, plastic | cream, milk, water, wine","VERB + JUG fill, pour sth into He filled a jug with juice. | pour, tip She poured a jug of water over his head. | empty, pour sth from/out o","PREP. ~ of a jug of milk"]},"media":{"img":["media/ldoce/img/jug.jpg","media/thumb/jug.jpg"],"uk":"media/ldoce/hwd/bre/8/jug0205.mp3","us":"media/ldoce/hwd/ame/5/jug.mp3"},"examples":[{"en":"She spilled a jug of water.","cn":"她把一罐子水弄洒了。"},{"en":"a five-gallon jug of beer","cn":"五加仑装的啤酒罐"}],"oxford":{"phon":"dʒʌɡ","pos":"noun","senses":[{"en":"a container with a handle and a lip, for holding and pouring liquids","cn":"（有把有嘴的）壶，罐","lab":"British English","ex":{"en":"a milk/water jug","cn":"奶杯；水罐"}},{"en":"a large round container with a small opening and a handle, and usually with a stopper or cap, for holding liquids","cn":"（细口带把的）大罐","lab":"North American English","ex":{"en":"a five-gallon jug of beer","cn":"五加仑装的啤酒罐"}},{"en":"the amount of liquid contained in a jug","cn":"一壶，一罐（的量）","ex":{"en":"She spilled a jug of water.","cn":"她把一罐子水弄洒了。"}},{"en":"an offensive word for a woman’s breasts","cn":"（冒犯语）乳房，奶子","g":"[plural]","lab":"taboo, offensive, slang，，，，"}]}},"jungle":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"热带丛林；密林","en":"A jungle is a forest in a tropical country where large numbers of tall trees and plants grow very close together.","ex":{"en":"...the mountains and jungles of Papua New Guinea","cn":"巴布亚新几内亚的山脉和丛林"}},{"pos":"N-SING 单数名词","cn":"堆满东西的地方；杂乱无章的地方","en":"If you describe a place as a jungle, you are emphasizing that it is full of lots of things and very untidy.","ex":{"en":"...a jungle of stuffed birds, knick-knacks, potted plants.","cn":"堆满了鸟类标本、小摆设和盆栽植物的乱七八糟的地方"}},{"pos":"N-SING 单数名词","cn":"复杂困难的境况；尔虞我诈的环境","en":"If you describe a situation as a jungle, you dislike it because it is complicated and difficult to get what you want from it.","ex":{"en":"Social security law and procedure remain a jungle of complex rules.","cn":"有关社会保障的法律和程序仍旧是个充满错综复杂的规则的危险领域。"}},{"pos":"PHRASE 短语","cn":"丛林法则；弱肉强食的原则","en":"If you refer to the law of the jungle, you are referring to a situation in which there are no laws or rules to govern the way that people behave and people use force to get what they want.","ex":{"en":"If you make aggression pay, this becomes the law of the jungle","cn":"如果你通过侵略谋取利益，这就成了弱肉强食。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"丛林音乐（一种有着快节奏鼓点的舞曲）","en":"Jungle is a style of dance music with a fast drum beat."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very large area of land with a lot of trees growing closely together","cn":""},{"en":"an area of land covered with a lot of trees, that is smaller than a forest","cn":""},{"en":"an area of land that is covered with trees – used especially for describing the type of land in an area","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A jungle is a forest thick with trees, other plants, and animals. Jungles are a little dangerous, which is what people mean when they say, \"It's a jungle out there!\""}]},"collocations":{"phrases":["ADJ. dense, impenetrable, thick | tropical | concrete, urban (figurative) This outback area is a far cry from the city's concrete jungle.","JUNGLE + NOUN warfare","PREP. in ~ a temple deep in the Brazilian jungle | through ~ They hacked their way through dense jungle."]},"media":{"uk":"media/ldoce/hwd/bre/0/jungle0205.mp3","us":"media/ldoce/hwd/ame/2/jungle.mp3"},"examples":[{"en":"It's a jungle out there — you've got to be strong to succeed.","cn":"那是个弱肉强食的地方，要成功就得是强者。"},{"en":"Our garden is a complete jungle.","cn":"我们的花园杂草丛生。"}],"oxford":{"phon":"ˈdʒʌŋɡl","pos":"noun","senses":[{"en":"an area of tropical forest where trees and plants grow very thickly","cn":"（热带）丛林，密林","g":"[uncountable, countable]","ex":{"en":"The area was covered in dense jungle.","cn":"这个地区丛林密布。"}},{"en":"a dangerous or unfriendly place or situation, especially one where it is very difficult to be successful or to trust anyone","cn":"弱肉强食的世界；危险地带","g":"[singular]","ex":{"en":"It's a jungle out there—you've got to be strong to succeed.","cn":"那是个弱肉强食的地方，要成功就得是强者。"}},{"en":"a type of electronic dance music developed in the UK in the early 1990s, which has a fast drum beat and a strong slower bass beat","cn":"鼓与贝斯，鼓打贝斯（一种电子舞曲，20 世纪 90 年代初兴起于英国，以快速的鼓点节拍和强劲缓慢的贝斯节奏为特点）","g":"[uncountable]"}]}},"jutland":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a peninsula (= a long thin area of land with sea on three sides ) in northern Europe belonging partly to Denmark and partly to Germany. The Battle of Jutland was fought between the British navy and German navy off the coast of Jutland in World War I.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/p028-000006840.mp3","us":"media/ldoce/hwd/ame/7/p028-000006840.mp3"}},"jumper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"针织套衫","en":"A jumper is a warm knitted piece of clothing which covers the upper part of your body and your arms.","ex":{"en":"Isabel had on a simple jumper and skirt.","cn":"伊莎贝尔穿着素净的针织套衫和裙子。"}},{"pos":"N-COUNT 可数名词","cn":"（穿在衬衫或毛线衫外的）无袖连衣裙","en":"A jumper is a sleeveless dress that is worn over a blouse or sweater.","ex":{"en":"She wore a checkered jumper and had ribbons in her hair.","cn":"她穿着格子连衣裙，头上系着丝带。"}},{"pos":"N-COUNT 可数名词","cn":"善跳跃者；跳跃的人（或动物）","en":"If you refer to a person or a horse as a particular kind of jumper, you are describing how good they are at jumping or the way that they jump.","ex":{"en":"He is a terrific athlete and a brilliant jumper","cn":"他是个出色的运动员，弹跳力非常好。"}},{"pos":"N-COUNT 可数名词","cn":"跳跃运动员","en":"A particular kind of jumper is an athlete who takes part in a particular jumping event.","ex":{"en":"Packer began her career as a long jumper.","cn":"帕克开始运动生涯时是个跳远运动员。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of clothing made of wool that covers the upper part of your body and arms","cn":"套头毛衣"},{"en":"a dress without sleeve s usually worn over a shirt 〔","cn":"通常穿在衬衣外面的〕无袖连衣裙"},{"en":"a person or animal that jumps","cn":"跳跃的人[动物]"}]},"collocations":{"phrases":["ADJ. baggy, loose, sloppy | tight | heavy, thick | light, thin | cashmere, cotton, woollen, woolly, etc. | knitted | crew-neck, polo-neck, t","VERB + JUMPER pull on | knit, make •"]},"media":{"uk":"media/ldoce/hwd/bre/b/jumper0205.mp3","us":"media/ldoce/hwd/ame/6/jumper.mp3"},"examples":[{"en":"He's a good jumper.","cn":"他的弹跳力特别好。"},{"en":"a woolly jumper","cn":"套头毛衣"}],"oxford":{"phon":"ˈdʒʌmpə(r)","pos":"noun","senses":[{"en":"a piece of clothing for the upper part of the body, made of wool or cotton, with long sleeves (= arms) and no buttons","cn":"套头衫；套头毛衣","lab":"British English","ex":{"en":"a woolly jumper","cn":"套头毛衣"}},{"en":"a loose dress without sleeves (= arms), usually worn over a blouse or sweater","cn":"背带裙，无袖连衣裙（通常穿在衬衣或套头衫外面）","lab":"North American English"},{"en":"a person, an animal or an insect that jumps","cn":"跳跃者；跳跃动物；跳虫","ex":{"en":"He's a good jumper.","cn":"他的弹跳力特别好。"}}]}},"juror":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"陪审团成员；陪审员","en":"A juror is a member of a jury."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a member of a jury","cn":"陪审员﹐陪审团成员"}]},"collocations":{"phrases":["VERB + JUROR swear in The jurors were sworn in."]},"media":{"uk":"media/ldoce/hwd/bre/f/juror0205.mp3","us":"media/ldoce/hwd/ame/9/juror.mp3"},"oxford":{"phon":"ˈdʒʊərə(r)","pos":"noun","senses":[{"en":"a member of a jury","cn":"陪审团成员；陪审员","ex":{"en":"The judge instructed jurors to disregard this information.","cn":"法官指示陪审员不要理会这一信息。"}}]}},"judo":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"柔道；柔术","en":"Judo is a sport in which two people fight and try to throw each other to the ground."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a Japanese sport or method of defence, in which you try to throw your opponent onto the ground","cn":"柔道"}]},"collocations":{"phrases":["VERB + JUDO do, practise","JUDO + NOUN hold, move, throw She managed to get the man in a judo hold. | mat","PHRASES a black, etc. belt in judo He's a black belt in judo. He's got a brown belt in judo. •"]},"media":{"uk":"media/ldoce/hwd/bre/5/judo0205.mp3","us":"media/ldoce/hwd/ame/5/judo.mp3"},"examples":[{"en":"She's a black belt in judo.","cn":"她是柔道黑带高手。"},{"en":"He does judo.","cn":"他是练柔道的。"}],"oxford":{"phon":"ˈdʒuːdəʊ","pos":"noun","senses":[{"en":"a sport in which two people fight and try to throw each other to the ground","cn":"柔道","ex":{"en":"He does judo.","cn":"他是练柔道的。"}}]}},"jurisdiction":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"司法权；审判权；管辖权","en":"Jurisdiction is the power that a court of law or an official has to carry out legal judgments or to enforce laws.","ex":{"en":"The British police have no jurisdiction over foreign bank accounts.","cn":"外国银行账户不在英国警方的管辖权限之内。"}},{"pos":"N-COUNT 可数名词","cn":"管辖区域；管辖范围","en":"A jurisdiction is a state or other area in which a particular court and system of laws has authority."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability or the right to control other people and make decisions that affect them","cn":""},{"en":"if someone has influence , they can use their important social position or their wealth to persuade other people to do things","cn":""},{"en":"the right to make decisions and control people, which a person has because of their job or official position","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Jurisdiction means having a legal right over something. A court can have jurisdiction over a legal question, a government can have jurisdiction over another country or territory. Even your parents could be said to have jurisdiction over you while you're under 18."}]},"collocations":{"phrases":["ADJ. limited | exclusive The commissioners had exclusive jurisdiction to decide. | civil, criminal, ecclesiastical","VERB + JURISDICTION have, retain The court has no jurisdiction in this case. | exercise The court may exercise its jurisdiction to compel th","PREP. beyond your ~ She acted beyond the jurisdiction of any teacher. | outside your ~ The matter is outside the jurisdiction of UK administ"]},"media":{"uk":"media/ldoce/hwd/bre/b/jurisdiction0205.mp3","us":"media/ldoce/hwd/ame/2/jurisdiction.mp3"},"examples":[{"en":"The committee has jurisdiction over all tax measures.","cn":"这个委员会有权制定所有税收措施。"}],"oxford":{"phon":"ˌdʒʊərɪsˈdɪkʃn","pos":"noun","senses":[{"en":"the authority that an official organization has to make legal decisions about somebody/something","cn":"司法权；审判权；管辖权","g":"[uncountable, countable]","ex":{"en":"The English court had no jurisdiction over the defendants.","cn":"英格兰法院对被告没有司法审判权。"}},{"en":"an area or a country in which a particular system of laws has authority","cn":"管辖区域；管辖范围","g":"[countable]","ex":{"en":"Practice varies between different European jurisdictions.","cn":"不同欧洲司法管辖区的做法有所不同。"}}]}},"junior":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"职位（或地位）较低的；年资较浅的","en":"A junior official or employee holds a low-ranking position in an organization or profession.","ex":{"en":"Junior and middle-ranking civil servants have pledged to join the indefinite strike.","cn":"基层和中层公务员已承诺要加入到无限期罢工中来。"}},{"pos":"N-SING 单数名词","cn":"较年幼者；年少者","en":"If you are someone's junior, you are younger than they are.","ex":{"en":"She now lives with actor Denis Lawson, 10 years her junior.","cn":"她现在与比她小10岁的演员丹尼斯·劳森同居。"}},{"pos":"N-IN-NAMES 名称名词","cn":"小（用于男子名后以区别于家族中同名的长辈，缩略形式为Jr）","en":"Junior is sometimes used after the name of the younger of two men in a family who have the same name, sometimes in order to prevent confusion. The abbreviation Jr is also used.","ex":{"en":"His son, Arthur Ochs Junior, is expected to succeed him as publisher.","cn":"他的儿子，小阿瑟·奥克斯，有望子承父业继续从事出版。"}},{"pos":"N-COUNT 可数名词","cn":"（美国高中或大学的）三年级学生","en":"In the United States, a student in the third year of a high school or university course is called a junior.","ex":{"en":"Their youngest daughter Amy's a junior at the University of Evansville in Indiana","cn":"他们的小女儿埃米是印第安纳州埃文斯维尔大学三年级的学生。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not old","cn":""},{"en":"a small child is very young. Little sounds more informal than small , and is used especially in spoken English","cn":""},{"en":"between the ages of 13 and 19","cn":""}]},"collocations":{"phrases":["VERBS be","ADV. very a very junior officer | comparatively, fairly, quite, relatively She's quite junior in the organization.","PREP. to John is still junior to me at work."]},"media":{"uk":"media/ldoce/hwd/bre/e/junior_adj0205.mp3","us":"media/ldoce/hwd/ame/7/junior1.mp3"},"examples":[{"en":"She has coached many of our leading juniors.","cn":"她训练过我们许多名列前茅的青少年运动员。"},{"en":"I leave junior with Mom when I'm at work.","cn":"我工作时就把儿子留给母亲照看。"}],"oxford":{"phon":"ˈdʒuːniə(r)","pos":"adjective","senses":[{"en":"having a low rank in an organization or a profession","cn":"地位（或职位、级别）低下的","g":"[usually before noun]","sc":"of low rank","ex":{"en":"a junior partner/minister/officer","cn":"初级合伙人；政务次长；初级官员"}},{"en":"connected with young people below a particular age, rather than with adults, especially in sports","cn":"青少年的","g":"[only before noun]","sc":"in sport","ex":{"en":"He's a member of the club's junior team.","cn":"他是俱乐部青年队的成员。"}},{"en":"(especially in the US) used after the name of a man who has the same name as his father, to make it clear who is being referred to","cn":"小（父子同名时置于儿子的姓名后以示区分）","sc":"son"},{"en":"for children under the age of 11 or 13","cn":"为 11 或 13 岁以下儿童设立的","g":"[only before noun]","lab":"British English","sc":"school/college","ex":{"en":"a junior school","cn":"小学"}},{"en":"connected with the year before the last year in a high school or college","cn":"（四年制高中或大学中）三年级生的，三年级的","g":"[only before noun]","lab":"North American English","sc":"school/college","ex":{"en":"I spent my junior year in France.","cn":"我三年级是在法国念的。"}},{"en":"a young person below a particular age, rather than an adult","cn":"青少年；青少年运动员","g":"[countable]","sc":"in sport","ex":{"en":"She has coached many of our leading juniors.","cn":"她训练过我们许多名列前茅的青少年运动员。"},"pos":"noun"},{"en":"a child who goes to junior school","cn":"小学生","g":"[countable]","lab":"British English","sc":"in school/college","ex":{"en":"Sam is going to be a junior next year.","cn":"萨姆明年就要上学了。"},"pos":"noun"},{"en":"a student in the year before the last year at high school or college","cn":"（四年制高中或大学的）三年级学生","g":"[countable]","lab":"North American English","sc":"in school/college","pos":"noun"},{"en":"a person who has a job at a low level within an organization","cn":"职位较低者；低层次工作人员","g":"[countable]","lab":"especially British English","sc":"low level job","ex":{"en":"office juniors","cn":"办公室的低级职员"},"pos":"noun"},{"en":"a person’s young son","cn":"男孩子；年幼的儿子","g":"[singular]","lab":"North American English, informal，，","sc":"son","ex":{"en":"I leave junior with Mom when I'm at work.","cn":"我工作时就把儿子留给母亲照看。"},"pos":"noun"}]}},"junk":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"废弃物；废旧物","en":"Junk is old and used goods that have little value and that you do not want any more.","ex":{"en":"Rose finds her furniture in junk shops","cn":"罗丝从旧货店买来了家具。"}},{"pos":"VERB 动词","cn":"丢弃；抛弃；废弃","en":"If you junk something, you get rid of it or stop using it.","ex":{"en":"Consumers will not have to junk their old cassettes to use the new format","cn":"消费者将不必丢弃他们的旧盒带而采用新的制式。"}},{"pos":"N-COUNT 可数名词","cn":"中国式（平底）帆船；舢板","en":"A junk is a Chinese sailing boat that has a flat bottom and square sails."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"use this when you are talking about two or more things of different types and you do not need to say what they are","cn":""},{"en":"objects or possessions of different types","cn":""},{"en":"things that are not useful and should be thrown away, for example because they are old or broken","cn":""}]},"collocations":{"phrases":["ADJ. old sculptures made from old junk and scrap metal","QUANT. bit, piece There were bits of junk lying around.","JUNK + VERB lie about/around","JUNK + NOUN shop | room They cleared out the junk room to make a tiny bedroom. | heap | material He made the boat out of junk materials."]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdejunk.mp3","us":"media/ldoce/hwd/ame/e/junk1.mp3"},"examples":[{"en":"I've cleared out all that old junk in the attic.","cn":"我把阁楼里所有的废旧杂物都清除干净了。"},{"en":"There's nothing but junk on the TV.","cn":"电视上全是些无聊的东西。"}],"oxford":{"phon":"dʒʌŋk","pos":"noun","senses":[{"en":"things that are considered to have no use or value","cn":"无用的东西；无价值的东西","g":"[uncountable]","lab":"informal, disapproving，，","ex":{"en":"I've cleared out all that old junk in the attic.","cn":"我把阁楼里所有的废旧杂物都清除干净了。"}},{"en":"food that is quick and easy to prepare and eat but that is thought to be bad for your health","cn":"垃圾食品（制作、食用方便却有害健康）","g":"[uncountable]","lab":"informal, disapproving，，"},{"en":"a Chinese boat with a square sail and a flat bottom","cn":"中国式帆船；戎克船","g":"[countable]"},{"en":"to get rid of something because it is no longer valuable or useful","cn":"把…当作废物扔弃；丢弃；废弃","ex":{"en":"All their old computers had been junked.","cn":"他们所有的旧电脑都被报废了。"},"pos":"verb"}]}},"junta":{"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"（武力夺取政权的）军事集团，军政府","en":"A junta is a military government that has taken power by force, and not through elections."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a government in which one person or group has total power and uses it unfairly and cruelly","cn":""},{"en":"a country where the police and other people who work for the government have too much power and control people's lives too much","cn":""},{"en":"a government run by a small group of army officers who have not been elected but have taken power by force","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When a government is overthrown, the coalition or group that forms and takes control is called a junta. If the military has seized control, as so often happens, then the group is called a military junta ."}]},"collocations":{"phrases":["ADJ. ruling | civilian, military, revolutionary","VERB + JUNTA form | dissolve, overthrow","JUNTA + VERB appoint sb The civilian junta appointed a prime minister.","JUNTA + NOUN leader, member"]},"media":{"uk":"media/ldoce/hwd/bre/1/ld44junta.mp3","us":"media/ldoce/hwd/ame/3/junta.mp3"},"oxford":{"phon":"ˈdʒʌntə","pos":"noun","senses":[{"en":"a military government that has taken power by force","cn":"（武力夺取政权的）军人集团，军政府","ex":{"en":"The civilian junta appointed a prime minister.","cn":"文官政府任命了首相。"}}]}},"jut":{"collins":{"senses":[{"pos":"VERB 动词","cn":"凸出；伸出","en":"If something juts out, it sticks out above or beyond a surface.","ex":{"en":"The northern end of the island juts out like a long, thin finger into the sea","cn":"岛屿的北端像一根细长的手指一样伸入海中。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（使身体部位）凸出；（尤指）翘起（下巴）","en":"If you jut a part of your body, especially your chin, or if it juts, you push it forward in an aggressive or determined way.","ex":{"en":"His jaw jutted stubbornly forward; he would not be denied","cn":"他的下巴倔强地翘着；他不会甘心被拒绝。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to stick out from a surface or through an opening","cn":""},{"en":"to stick out and point upwards","cn":""},{"en":"to stick out, especially to stick out further than is usual or expected","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When something juts , it extends outward. Your nose juts out from your face, just as your ears jut from your head. If you’re feeling determined, you might jut out your chin."}]},"media":{"uk":"media/ldoce/hwd/bre/e/jut0205.mp3","us":"media/ldoce/hwd/ame/7/jut.mp3"},"examples":[{"en":"A row of small windows jutted out from the roof.","cn":"有一排小窗户从房顶上突出来。"},{"en":"She jutted her chin out stubbornly.","cn":"她倔强地把下巴翘得高高的。"}],"oxford":{"phon":"dʒʌt","pos":"verb","senses":[{"en":"to stick out further than the surrounding surface, objects, etc.; to make something stick out","cn":"（使）突出，伸出","ex":{"en":"A row of small windows jutted out from the roof.","cn":"有一排小窗户从房顶上突出来。"}}]}}});
